//
//  AppViewModel.kt
//  Generated by lecodes app init — yours to edit.
//
//  The engine lives here so it survives configuration changes (rotation recreates the
//  Activity, not the ViewModel); onCleared is the one "never coming back" signal where the
//  engine's system registrations are released.
//

package com.example.aidealautodiaglecodes

import android.app.Activity
import android.app.Application
import androidx.lifecycle.AndroidViewModel
import io.letary.lecodes.LeCodesShell
import io.letary.lecodes.LecodesEngine

class AppViewModel(application: Application) : AndroidViewModel(application) {

    val engine: LecodesEngine = LecodesEngine(application.applicationContext)

    init {
        // `// preload:` assets (images, fonts) resolve out of app/src/main/assets/ —
        // `lecodes app sync` copies them there flat by name.
        engine.onFetchLocal = { path ->
            getApplication<Application>().assets.open(path).use { it.readBytes() }
        }
    }

    override fun onCleared() {
        engine.dispose()
        super.onCleared()
    }

    private var isCreated = false
    fun onActivityCreate(activity: Activity) {
        engine.attach(activity)
        if (!isCreated) {
            // OTA (native, no JS involved): LeCodesShell.boot takes the newest local bundle (a
            // downloaded update, or the embedded assets/app.js) and starts the check BEFORE it runs
            // — even a bundle that crashes on boot can never block its own fix. The first launch of
            // this binary waits for the check (5 s at most; the splash stays, the first frame is
            // held) and runs the newest bundle; later launches run at once and new code applies on
            // the next launch. Configured via app.json "update" (→ the runtime module's manifest
            // meta-data); offline: no wait.
            if (!LeCodesShell.boot(engine, activity)) {
                android.util.Log.e("LeCodes", "bundled app.js is missing — run `lecodes app sync`")
            }
            isCreated = true
        }
    }
}
